local UIActionPointRankDialog = Class("UIActionPointRankDialog")

------------ lifeCycle ------------

function UIActionPointRankDialog:__init()
    self:CleanProperties()
end

function UIActionPointRankDialog:__delete()
    self:CleanProperties()
end

function UIActionPointRankDialog:Awake()
end

function UIActionPointRankDialog:OnInitialize()
    xTry(function()
        local params = self.controller.Argument.parameters
        self.comp = params.comp
        self.rankData = self.comp:GetRankData()
        self.myRankData = self.comp:GetMyRankData()
        self:InitComponent()
    end)
end

function UIActionPointRankDialog:OnShow()
    xTry(function()
        GameUtils.HidePreviousDialogs(self.controller)
        if IsNull(self.rankData) or #self.rankData == 0 then
            self:ShowBlank()
        else
            self:RefreshMyselfNode()
            self:RefreshLoopViewList(#self.rankData)
        end
    end)
end

function UIActionPointRankDialog:OnFocus(focus)
    if focus then
        -- 红点
        local hasTips = self.comp:GetRankDailyRedPoint()
        KTool.SetActive(self.RT_DailyRewardRedPoint, hasTips >= 0)
    end
end

function UIActionPointRankDialog:OnFinalize()
    xTry(function()
        GameUtils.ShowPreviousDialogs(self.controller)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

------------ lifeCycle ------------

function UIActionPointRankDialog:CleanProperties()
end

function UIActionPointRankDialog:InitComponent()
    UIEventProxy.Create(self.RT_RankDamageBtn.gameObject).onPointerClick = Bind(self.comp, self.comp.OnRankDamageBtnClicked)
    UIEventProxy.Create(self.RT_RewardPreviewBtn.gameObject).onPointerClick = Bind(self.comp, self.comp.OnRankRewardPreviewBtnClicked)
    UIEventProxy.Create(self.RT_DailyRewardBtn.gameObject).onPointerClick = Bind(self.comp, self.comp.GetRankDailyReward)

    -- 红点
    local hasTips = self.comp:GetRankDailyRedPoint()
    KTool.SetActive(self.RT_DailyRewardRedPoint, hasTips >= 0)
end

--- 显示空白榜单
function UIActionPointRankDialog:ShowBlank()
    KTool.SetActive(self.RT_MyRankNode, false)
    KTool.SetActive(self.RT_EmptyNode, true)
end

--- 更新显示我自己的排行信息
function UIActionPointRankDialog:RefreshMyselfNode()
    local LB_myCell = GetLuaBehaviour(self.RT_MyRankNode.gameObject, RankCellLuaPath)
    LB_myCell.Env:SetComponent(self.comp)
    LB_myCell.Env:Refresh(self.myRankData)
end

--- 排行榜列表
---@param maxNum any
function UIActionPointRankDialog:RefreshLoopViewList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function UIActionPointRankDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, RankCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        -- 第一页的节点播放延迟出现的动画
        if index + 1 <= loopListView.DisplayItemCount then
            CfUtils.PlayDelayShowAnimation(cell, index)
        end
    end
    local data = self.rankData[index + 1]
    local LT_cell = LB_cell.Env
    LT_cell:SetComponent(self.comp)
    LT_cell:Refresh(data)

    return cell
end

return UIActionPointRankDialog
